from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class GetRunningTestModelsCPCONFIGV1(SchemaObject):
    nr_cell_id = SchemaField(name="nrCellId", not_null=True)
    cell_name = SchemaField(name="cellName", optional=True)
    test_type = SchemaField(name="testType", not_null=True)
    frc_index = SchemaField(name="frcIndex", optional=True)
    performance_test_type = SchemaField(name="performanceTestType", optional=True)
    pusch_frc_index = SchemaField(name="puschFrcIndex", optional=True)
    pucch_format = SchemaField(name="pucchFormat", optional=True)
    prach_configuration_index = SchemaField(name="prachConfigurationIndex", optional=True)
    test_model = SchemaField(name="testModel", optional=True)

    def __init__(self, nr_cell_id=None, cell_name=None, test_type=None, frc_index=None, performance_test_type=None,
                 pusch_frc_index=None, pucch_format=None, prach_configuration_index=None, test_model=None):
        self.nr_cell_id = nr_cell_id
        self.cell_name = cell_name
        self.test_type = test_type
        self.frc_index = frc_index
        self.performance_test_type = performance_test_type
        self.pusch_frc_index = pusch_frc_index
        self.pucch_format = pucch_format
        self.prach_configuration_index = prach_configuration_index
        self.test_model = test_model

        super(GetRunningTestModelsCPCONFIGV1, self).__init__()
